(()=>{if(!document.body.classList.contains('ebook-detail')||!matchMedia('(pointer:fine)').matches)return;const key='jh_ebook_exit_prompt_v1',days=14*864e5;try{const t=Number(localStorage.getItem(key)||0);if(t&&Date.now()-t<days)return}catch{}const d=document.createElement('dialog');d.className='newsletter-exit-dialog';d.setAttribute('aria-labelledby','newsletter-exit-title');d.innerHTML=`<form method="dialog" class="newsletter-exit-dialog__close"><button type="submit" aria-label="Close sign-up prompt">×</button></form><div data-newsletter-shell><h2 id="newsletter-exit-title">Want the useful bits before you go?</h2><p>Get the weekday AI briefing and the free plain-English glossary cheat sheet.</p><form class="newsletter-native-form" action="/api/newsletter/subscribe" method="post" data-newsletter-form><label>Email address <input name="email" type="email" autocomplete="email" inputmode="email" maxlength="254" required placeholder="you@example.com"></label><input type="hidden" name="source" value="ebook-exit"><input type="hidden" name="next" value="/downloads/ai-glossary-cheat-sheet/"><span class="newsletter-honeypot" aria-hidden="true"><label>Company <input name="company" tabindex="-1" autocomplete="off"></label></span><button class="button" type="submit">Join and get the cheat sheet</button><p class="subtle" data-newsletter-status hidden aria-live="polite"></p></form><p class="newsletter-fallback-copy"><a data-newsletter-fallback href="https://form.jotform.com/260277027608054" target="_blank" rel="noopener">Hosted sign-up fallback</a></p></div>`;document.body.appendChild(d);let shown=false;const mark=()=>{try{localStorage.setItem(key,String(Date.now()))}catch{}};const show=e=>{if(shown||e.clientY>8||!d.showModal)return;shown=true;mark();d.showModal();document.removeEventListener('mouseout',show)};d.addEventListener('close',mark);document.addEventListener('mouseout',show);})();
